-- ===================== Part 2: raw-SQL invariants =====================

-- At most ONE live (non-reversed) ORDER_PAYMENT allocation per order and per attempt.
-- A second credit for the same order must become OVERCOLLECTION, never a second release.
CREATE UNIQUE INDEX "PgAllocation_one_live_order_payment_per_order"
  ON "PgAllocation" ("orderId")
  WHERE "kind" = 'ORDER_PAYMENT' AND "reversedAt" IS NULL;

CREATE UNIQUE INDEX "PgAllocation_one_live_order_payment_per_attempt"
  ON "PgAllocation" ("attemptId")
  WHERE "kind" = 'ORDER_PAYMENT' AND "reversedAt" IS NULL;

-- Merchant binding (D7): a gateway merchant id may back only one VERIFIED account,
-- and a restaurant has at most one VERIFIED receiving account at a time.
CREATE UNIQUE INDEX "PgReceivingAccount_verified_gatewayMerchantId"
  ON "PgReceivingAccount" ("gatewayMerchantId")
  WHERE "status" = 'VERIFIED';

CREATE UNIQUE INDEX "PgReceivingAccount_verified_restaurantId"
  ON "PgReceivingAccount" ("restaurantId")
  WHERE "status" = 'VERIFIED';

-- Money is strictly positive integer paise wherever an amount denotes a money movement.
ALTER TABLE "PgPaymentAttempt"   ADD CONSTRAINT "PgPaymentAttempt_expectedAmountPaise_pos" CHECK ("expectedAmountPaise" > 0);
ALTER TABLE "PgPaymentEvidence"  ADD CONSTRAINT "PgPaymentEvidence_observedAmountPaise_pos" CHECK ("observedAmountPaise" IS NULL OR "observedAmountPaise" > 0);
ALTER TABLE "PgBankTransaction"  ADD CONSTRAINT "PgBankTransaction_amountPaise_pos" CHECK ("amountPaise" > 0);
ALTER TABLE "PgAllocation"       ADD CONSTRAINT "PgAllocation_amountPaise_pos" CHECK ("amountPaise" > 0);
ALTER TABLE "PgLimitReservation" ADD CONSTRAINT "PgLimitReservation_amountPaise_pos" CHECK ("amountPaise" > 0);
ALTER TABLE "PgRefundRecord"     ADD CONSTRAINT "PgRefundRecord_amountPaise_pos" CHECK ("amountPaise" > 0);
ALTER TABLE "PgReceivingAccount" ADD CONSTRAINT "PgReceivingAccount_maxAmountPaise_pos" CHECK ("maxAmountPaise" IS NULL OR "maxAmountPaise" > 0);
ALTER TABLE "PgAccountDailyUsage" ADD CONSTRAINT "PgAccountDailyUsage_reserved_nonneg" CHECK ("reserved" >= 0);
-- Bank references are stored normalized (trimmed, upper-case, no whitespace) and non-empty.
ALTER TABLE "PgBankTransaction"  ADD CONSTRAINT "PgBankTransaction_bankReference_normalized"
  CHECK ("bankReference" <> '' AND "bankReference" = upper("bankReference") AND "bankReference" !~ '\s');

-- PgFinancialEvent is append-only: any UPDATE or DELETE raises.
CREATE OR REPLACE FUNCTION "pg_financial_event_append_only"() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'PgFinancialEvent is append-only (% blocked)', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "PgFinancialEvent_append_only"
  BEFORE UPDATE OR DELETE ON "PgFinancialEvent"
  FOR EACH ROW EXECUTE FUNCTION "pg_financial_event_append_only"();
